/**
 * NativeMetadataService — Main Process metadata boundary.
 *
 * Phase 2 Foundation: Stub implementation that validates URLs and returns
 * mock metadata using only Node.js-compatible APIs (no window.setTimeout,
 * no DOM APIs).
 *
 * In Phase 2.x this will invoke yt-dlp via child_process to extract real
 * metadata from YouTube URLs.
 */
import type { AnalysisResult, VideoMetadata } from "../../src/types/download";

const YOUTUBE_PATTERN = /^https?:\/\/(www\.)?(youtube\.com|youtu\.be)\//;

function isYouTubeUrl(url: string): boolean {
  return YOUTUBE_PATTERN.test(url);
}

function inferLinkType(url: string): "video" | "playlist" | "playlist-video" | "shorts" | "channel" {
  try {
    const parsed = new URL(url);
    const pathname = parsed.pathname.toLowerCase();

    if (pathname.includes("/shorts/")) return "shorts";
    if (pathname.includes("/channel/") || pathname.includes("/@")) return "channel";
    if (parsed.searchParams.has("list") && parsed.searchParams.has("v")) return "playlist-video";
    if (parsed.searchParams.has("list")) return "playlist";
  } catch {
    // fall through
  }
  return "video";
}

function createVideoStub(url: string): VideoMetadata {
  return {
    id: `native-video-stub`,
    sourceUrl: url,
    linkType: "video",
    thumbnail: `https://picsum.photos/seed/native-stub/320/180`,
    title: "Video (Native Stub — yt-dlp not connected yet)",
    channelName: "Native Channel",
    duration: "00:00",
    views: 0,
    qualityOptions: ["1080p", "720p", "480p"],
    videoFormats: ["mp4"],
    audioFormats: ["m4a"],
    resolution: "1080p",
    fps: 30,
    videoCodec: "H.264",
    audioCodec: "AAC",
    videoBitrate: "0 Mbps",
    audioBitrate: "0 Kbps",
    container: "mp4",
    fileSize: 0,
    uploadDate: new Date().toISOString().split("T")[0]
  };
}

export class NativeMetadataService {
  async analyze(url: string): Promise<AnalysisResult> {
    if (!url || typeof url !== "string") {
      throw new Error("Invalid URL: must be a non-empty string");
    }

    if (!isYouTubeUrl(url)) {
      throw new Error("unsupported_url");
    }

    const linkType = inferLinkType(url);

    // Phase 2.x: Replace this stub with actual yt-dlp child_process invocation
    return createVideoStub(url);
  }
}
